1	import { Router } from "express";
2	import { eq } from "drizzle-orm";
3	import type { Db } from "@paperclipai/db";
4	import { authUsers } from "@paperclipai/db";
5	import {
6	  authSessionSchema,
7	  currentUserProfileSchema,
8	  updateCurrentUserProfileSchema,
9	} from "@paperclipai/shared";
10	import { unauthorized } from "../errors.js";
11	import { expressHandler } from "../http/express-adapter.js";
12	import type { Handler } from "../http/types.js";
13	import type { StorageService } from "../storage/types.js";
14	
15	async function loadCurrentUserProfile(db: Db, userId: string) {
16	  const user = await db
17	    .select({
18	      id: authUsers.id,
19	      email: authUsers.email,
20	      name: authUsers.name,
21	      image: authUsers.image,
22	    })
23	    .from(authUsers)
24	    .where(eq(authUsers.id, userId))
25	    .then((rows) => rows[0] ?? null);
26	
27	  if (!user) {
28	    throw unauthorized("Signed-in user not found");
29	  }
30	
31	  return currentUserProfileSchema.parse({
32	    id: user.id,
33	    email: user.email ?? null,
34	    name: user.name ?? null,
35	    image: user.image ?? null,
36	  });
37	}
38	
39	function buildHandlers(db: Db) {
40	  // server/src/routes/auth.ts:40
41	  const getSession: Handler = async (ctx) => {
42	    if (ctx.actor?.type !== "board" || !ctx.actor.userId) {
43	      throw unauthorized("Board authentication required");
44	    }
45	
46	    const user = await loadCurrentUserProfile(db, ctx.actor.userId);
47	    return Response.json(authSessionSchema.parse({
48	      session: {
49	        id: `paperclip:${ctx.actor.source}:${ctx.actor.userId}`,
50	        userId: ctx.actor.userId,
51	      },
52	      user,
53	    }));
54	  };
55	
56	  // server/src/routes/auth.ts:55
57	  const getProfile: Handler = async (ctx) => {
58	    if (ctx.actor?.type !== "board" || !ctx.actor.userId) {
59	      throw unauthorized("Board authentication required");
60	    }
61	
62	    return Response.json(await loadCurrentUserProfile(db, ctx.actor.userId));
63	  };
64	
65	  // server/src/routes/auth.ts:63
66	  const patchProfile: Handler = async (ctx) => {
67	    if (ctx.actor?.type !== "board" || !ctx.actor.userId) {
68	      throw unauthorized("Board authentication required");
69	    }
70	
71	    const body = await ctx.json();
72	    const patch = updateCurrentUserProfileSchema.parse(body);
73	    const now = new Date();
74	
75	    const updated = await db
76	      .update(authUsers)
77	      .set({
78	        name: patch.name,
79	        ...(patch.image !== undefined ? { image: patch.image } : {}),
80	        updatedAt: now,
81	      })
82	      .where(eq(authUsers.id, ctx.actor.userId))
83	      .returning({
84	        id: authUsers.id,
85	        email: authUsers.email,
86	        name: authUsers.name,
87	        image: authUsers.image,
88	      })
89	      .then((rows) => rows[0] ?? null);
90	
91	    if (!updated) {
92	      throw unauthorized("Signed-in user not found");
93	    }
94	
95	    return Response.json(currentUserProfileSchema.parse({
96	      id: updated.id,
97	      email: updated.email ?? null,
98	      name: updated.name ?? null,
99	      image: updated.image ?? null,
100	    }));
101	  };
102	
103	  return { getSession, getProfile, patchProfile };
104	}
105	
106	export function authRoutes(db: Db) {
107	  const router = Router();
108	  const { getSession, getProfile, patchProfile } = buildHandlers(db);
109	
110	  // None of these handlers touch storage; supply a sentinel so expressHandler's
111	  // AdapterDeps type is satisfied without widening the public signature.
112	  const storageSentinel = new Proxy({} as StorageService, {
113	    get(_target, prop) {
114	      throw new Error(`auth handler unexpectedly accessed storage.${String(prop)}`);
115	    },
116	  });
117	  const deps = { db, storage: storageSentinel };
118	
119	  router.get("/get-session", expressHandler(getSession, deps));
120	  router.get("/profile", expressHandler(getProfile, deps));
121	  router.patch("/profile", expressHandler(patchProfile, deps));
122	
123	  return router;
124	}
